 "content": "from collections import deque


def transform(grid):
    """Erase the smallest 4-connected nonzero object."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append(comp)
    if not components:
        return [row[:] for row in grid]
    target = min(components, key=len)
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = 0
    return out


def component_sizes(grid):
    """Return component sizes for inspection/testing."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    sizes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            n = 0
            while q:
                y, x = q.popleft()
                n += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            sizes.append(n)
    return sizes
